    var BIND = ['clip', 'staple', 'binder', 'pin', 'tape', 'fold'], TONE = ['cream', 'white', 'mist', 'kraft', 'ledger'], ROTS = [1.5, -1.2, 2.2, -2, .6, -.6, 1.8];
